"""v5 controlled AI budget policies. All physical/economic game rules stay v4.

No special grants, forced buyers, price or score changes. 'stock_guard' is an
EXPERIMENT, not a new production rule: automatic agents may postpone input
shopping, and the unchanged G1 safety-production rule still applies.
"""
from __future__ import annotations
from dataclasses import dataclass
from collections import Counter
from copy import copy
import math
from expansion_engine import Game as V4Game
from reference_engine import GOODS, FOOD, DURABLES, BONUS


@dataclass(frozen=True)
class Policy:
    funded_development: bool = False
    living_first: bool = False
    household_guard: bool = False
    stock_guard: bool = False


POLICIES = {
    'baseline': Policy(),
    'funded': Policy(funded_development=True),
    'living': Policy(funded_development=True, living_first=True),
    'balanced': Policy(funded_development=True, living_first=True, household_guard=True),
    'stock_guard': Policy(funded_development=True, living_first=True, stock_guard=True),
}


class Game(V4Game):
    def __init__(self, seed=0, variant='baseline', focal=None, style='normal',
                 trade_enabled=True):
        if variant not in POLICIES:
            raise ValueError('unknown policy')
        self.variant = variant
        self.policy = POLICIES[variant]
        self.funding_blocks = []
        self.household_blocks = []
        self.input_deferrals = set()
        self.stock_plan_cache = {}
        super().__init__(seed, 'roles', focal=focal, style=style,
                         fixes=True, trade_enabled=trade_enabled)

    def projected_resources(self, c, project=None):
        """Pure next-cycle requirements AFTER a proposed investment.

        Development materials are separate, consumed before these inputs.
        The physical production recipe is inherited unchanged from v4.
        """
        if self.r >= 9:
            return Counter()
        p = copy(c)
        p.levels = dict(c.levels)
        if project:
            level = p.levels.get(project, 0) + 1
            p.levels[project] = level
            if project == 'machine':
                p.machine_tech = min(3, level)
            if project == 'electronics':
                p.elec_tech = min(3, level)
        need = Counter()
        for good in p.levels:
            need.update(self.resource_requirements(p, good, self.r + 1))
        return need

    def excessive_current_stock(self, c, good):
        if good not in DURABLES or good not in c.levels:
            return False
        # Do not mistake an obsolete stockpile for available new-grade products.
        grade = self.tech_for(c, good)
        unused = sum(self.units[i].origin == c.name and not self.units[i].used
                     and self.units[i].gen >= grade
                     for i in self.ids(c, good, False))
        protected = math.ceil(self.pop()/2) if good == 'electronics' else self.equip_slots(c)
        cycle = self.base_quantity(c, good) + (BONUS[good] if c.focus == good else 0)
        return max(0, unused - protected) > 2 * cycle

    def next_resources(self, c):
        if not self.policy.stock_guard or c.style in ('idle', 'invest'):
            return super().next_resources(c)
        if self.r >= 9:
            return Counter()
        need = Counter()
        for good in c.levels:
            if self.excessive_current_stock(c, good):
                continue
            need.update(self.resource_requirements(c, good, self.r+1))
        return need

    def plan(self, c):
        if not self.policy.stock_guard or c.style in ('idle', 'invest'):
            return super().plan(c)
        key = (self.r, c.name)
        if key not in self.stock_plan_cache:
            project = super().plan(c)
            if project and self.excessive_current_stock(c, project):
                project = None
            self.stock_plan_cache[key] = project
            self.plan_cache[key] = project
        return self.stock_plan_cache[key]

    def targets(self, c):
        t = super().targets(c)
        if not self.policy.funded_development:
            return t
        project = self.plan(c)
        # Preserve the v4 research-shopping affordability gate; the only change
        # is to count the subsequent production recipe as well as development.
        if project and c.cash >= self.upgrade_cost(c, project) + 20:
            post = self.projected_resources(c, project)
            research_ore, _ = self.upgrade_requirements(c, project)
            for raw in ('ore', 'fuel'):
                t[raw] = max(t[raw], post[raw] + (research_ore if raw == 'ore' else 0))
        return t

    def purchase_plan(self, c):
        if not self.policy.living_first:
            return super().purchase_plan(c)
        if c.style == 'idle' or not self.opt.trade_enabled:
            return []
        wallet = c.cash
        t = self.targets(c)
        plan = []
        virtual = {g:self.count(c, g) for g in GOODS}
        grades = {g:[self.units[i].gen for i in self.ids(c, g)] for g in DURABLES}
        project = self.plan(c)
        mg = self.upgrade_requirements(c, project)[1] if project else 0

        def add(good, want, min_gen=1, kind='need', hold=0):
            nonlocal wallet
            if want <= 0:
                return
            offers = [o.price for o in self.orders.values()
                      if o.good == good and o.gen >= min_gen and o.seller != c.name]
            price = min(offers) if offers else self.quote(good, min_gen)
            cushion = 0 if c.style == 'invest' or good in FOOD else 15
            qty = min(want, max(0, wallet-cushion-hold)//price)
            budget = qty * price
            plan.append({'good':good, 'want':want, 'quantity':qty, 'unit_price':price,
                         'budget':budget, 'min_gen':min_gen, 'kind':kind})
            wallet -= budget
            virtual[good] += qty
            if good in DURABLES:
                grades[good] += [min_gen] * qty

        # A controlled order change only. An unfilled household quantity comes
        # before operating inputs; optional newer-model replacement stays last.
        for good in ('wheat', 'banana', 'electronics', 'ore', 'fuel', 'machine'):
            want = max(0, t[good]-virtual[good])
            grade = mg if good == 'machine' and mg else 1
            if good == 'machine' and mg and max(grades[good], default=0) < mg:
                want = max(1, want)
            hold = 0
            if good == 'machine':
                hold = (self.upgrade_cost(c,project)+self.reserve(c)) if mg else self.prep_budget(c)
            add(good, want, grade, hold=hold)
        if self.flag('upgrade_living_goods') and self.r <= 7:
            used = sorted(grades['electronics'], reverse=True)[:math.ceil(self.pop()/2)]
            if len(used) == math.ceil(self.pop()/2) and used and min(used) < self.global_gen['electronics']:
                add('electronics', 1, min(used)+1, 'replacement', self.reserve(c)+self.prep_budget(c))
        assert sum(x['budget'] for x in plan) <= c.cash
        return plan

    def buy_phase(self, c, sweep):
        if self.policy.stock_guard and c.style not in ('idle', 'invest') and self.r < 9:
            target = self.targets(c)
            full = self.projected_resources(c)
            for good in c.levels:
                recipe = self.resource_requirements(c,good,self.r+1)
                reduced = any(target[raw] < full[raw] and self.count(c,raw) < full[raw]
                              for raw in recipe)
                if self.excessive_current_stock(c, good) and reduced:
                    self.input_deferrals.add((self.r, c.name, good))
        return super().buy_phase(c, sweep)

    def invest(self, c, action_id=None):
        if action_id is not None and (not isinstance(action_id,str) or not action_id):
            return False
        if not self.policy.funded_development:
            return super().invest(c, action_id)
        if action_id is not None and action_id in self.invest_actions:
            return super().invest(c, action_id)
        if (self.r,c.name) in self.invested_rounds or c.style in ('idle','trade') or self.r >= 8:
            return super().invest(c, action_id)
        project = self.plan(c)
        if project:
            reserve = 0 if c.style == 'invest' else self.reserve(c)
            if c.cash >= self.upgrade_cost(c,project)+reserve:
                if self.policy.household_guard and c.style != 'invest':
                    food_met = self.r in c.satisfied_rounds
                    living_met = self.count(c,'electronics') >= math.ceil(self.pop()/2)
                    if not food_met or not living_met:
                        self.household_blocks.append({'round':self.r,'country':c.name,
                            'project':project,'food_met':food_met,'living_quantity_met':living_met})
                        if action_id is not None:
                            self.invest_actions[action_id] = False
                            self.invest_payloads[action_id] = (self.r,c.name)
                        return False
                required = self.projected_resources(c, project)
                research, _ = self.upgrade_requirements(c, project)
                required['ore'] += research
                missing = {g:q-self.count(c,g) for g,q in required.items() if self.count(c,g) < q}
                if missing:
                    self.funding_blocks.append({'round':self.r,'country':c.name,
                        'project':project,'missing_after_development':missing})
                    # This is an automatic-agent decision, NOT a new legal
                    # investment constraint for student commands in a web app.
                    if action_id is not None:
                        self.invest_actions[action_id] = False
                        self.invest_payloads[action_id] = (self.r,c.name)
                    return False
        return super().invest(c, action_id)

files.trade_v17/source_v13/raw_engine.py:
"""v8: starter resources and MACHINE-ONLY material efficiency on v7 price.

The 2-to-1 credit experiment increases machine input intensity at unchanged
bundle prices. It is NOT a global half-size commodity redenomination.
Electronics recipes, development materials, cash, pricing, agents and scores
are inherited. No automatic buyer, subsidy, forced use or new score exists.
"""
from __future__ import annotations

from collections import Counter
from dataclasses import dataclass, asdict
import math
import statistics

from recommendation_engine import Game as V7
from budget_trace import Game as PhysicalChecks
from machinery_engine import UPKEEP_USES
from reference_engine import GOODS

RAW_GOODS = ('ore', 'fuel')
SOURCE_KINDS = ('initial_own', 'initial_foreign', 'produced_own', 'produced_foreign')


@dataclass(frozen=True)
class RawPolicy:
    machine_credits: int = 2
    starter: str = 'legacy'

    def __post_init__(self):
        if type(self.machine_credits) is not int or self.machine_credits not in (1, 2):
            raise ValueError('machine credits must be 1 or 2')
        if self.starter not in ('legacy', 'first_cycle', 'two_cycles', 'none'):
            raise ValueError('unknown starter profile')


RAW_MODES = {
    'baseline': RawPolicy(2, 'legacy'),
    'starter': RawPolicy(2, 'first_cycle'),
    'bridge': RawPolicy(2, 'two_cycles'),
    'recipe': RawPolicy(1, 'legacy'),
    'coupled': RawPolicy(1, 'first_cycle'),
    'no_starter': RawPolicy(2, 'none'),
    'strict_no_starter': RawPolicy(1, 'none'),
}
REFUSAL_STYLES = {'no_ore': ('ore',), 'no_fuel': ('fuel',), 'no_raw': RAW_GOODS}


class Game(V7):
    def __init__(self, seed=0, variant='baseline', focal=None, style='normal', trade_enabled=True):
        if variant not in RAW_MODES:
            raise ValueError('unknown raw-resource variant')
        self.raw_variant = variant
        self.raw_policy = RAW_MODES[variant]
        self.raw_initializing = True
        self.raw_use_log = []
        self.raw_round_ledger = []
        self.starter_allocation = {}
        self.raw_refusal_country = focal if style in REFUSAL_STYLES else None
        self.raw_refusal_goods = REFUSAL_STYLES.get(style, ())
        super().__init__(seed, variant='price', focal=focal,
                         style='normal' if style in REFUSAL_STYLES else style,
                         trade_enabled=trade_enabled)
        self.raw_initializing = False
        if self.raw_refusal_goods and self.raw_refusal_country not in self.cs:
            raise ValueError('resource refusal requires a valid focal country')
        if self.raw_policy.starter in ('first_cycle', 'two_cycles'):
            # Production precedes trading. Supply exactly round-one actual
            # requirements. The bridge additionally funds the second cycle at
            # the STARTING technology/focus, never a prospective upgrade.
            for c in self.cs.values():
                required = Counter()
                cycles = (1,2) if self.raw_policy.starter == 'two_cycles' else (1,)
                for cycle in cycles:
                    for good in c.levels:
                        if good == 'machine':
                            q = self.machine_quantity(c, cycle, actual=True)
                            required.update(self.material_plan(c, cycle, q)['required'])
                        else:
                            required.update(self.resource_requirements(c, good, cycle))
                for raw in RAW_GOODS:
                    if required[raw]:
                        self.mint(c, raw, required[raw], initial=True)
        self.starter_allocation = {
            n: {g:self.count(c, g, False) for g in RAW_GOODS} for n,c in self.cs.items()
        }
        # Same asset formula, using the goods actually granted. No compensating
        # cash is added; this baseline shift is reported separately from scores.
        self.initial_assets = {n:c.cash+self.stock_value(c) for n,c in self.cs.items()}

    def mint(self, c, g, n, gen=1, initial=False):
        if initial and self.raw_initializing and g in RAW_GOODS and self.raw_policy.starter != 'legacy':
            n = 0
        return super().mint(c, g, n, gen, initial)

    def material_plan(self, c, production_round, quantity=None):
        # Parent chooses raw by round/specialization, generation and scoped key.
        # Recompute only the batch/credit arithmetic; never change a module global.
        plan = super().material_plan(c, production_round, quantity)
        before = plan['credits_before']
        spent = plan['credits_spent']
        size = self.raw_policy.machine_credits
        batches = math.ceil(max(0, spent-before)/size)
        plan.update(required={plan['raw']:batches} if batches else {},
                    raw_spent=batches, credits_after=before+size*batches-spent,
                    credits_per_raw=size)
        return plan

    def purchase_plan(self, c):
        rows = super().purchase_plan(c)
        if c.name == self.raw_refusal_country:
            return [row for row in rows if row['good'] not in self.raw_refusal_goods]
        return rows

    def settle_transaction(self, legs, cash, channel, action_id):
        if self.raw_refusal_country and isinstance(legs, list):
            for leg in legs:
                if isinstance(leg, dict) and leg.get('buyer') == self.raw_refusal_country:
                    ids = leg.get('ids', [])
                    if not isinstance(ids, list):
                        return False
                    if any(type(i) is int and i in self.units and
                           self.units[i].good in self.raw_refusal_goods for i in ids):
                        return False
        return super().settle_transaction(legs, cash, channel, action_id)

    def consume(self, c, g, n, purpose):
        selected = super().consume(c, g, n, purpose)
        if g in RAW_GOODS:
            for uid in selected:
                u = self.units[uid]
                source = ('initial_' if u.born == 0 else 'produced_') + ('own' if u.origin == c.name else 'foreign')
                self.raw_use_log.append({
                    'round':self.r, 'country':c.name, 'good':g, 'purpose':purpose,
                    'uid':uid, 'born':u.born, 'origin':u.origin, 'source':source,
                    'import_transaction':u.last_import,
                })
        return selected

    def _raw_counts(self, name, good, round_number=None):
        uses = [e for e in self.raw_use_log if e['country']==name and e['good']==good
                and (round_number is None or e['round']==round_number)]
        return {
            'consumed':len(uses),
            'production':sum(e['purpose']=='production' for e in uses),
            'research':sum(e['purpose']=='development' for e in uses),
            'imported_used':sum(e['import_transaction'] is not None for e in uses),
            **{source:sum(e['source']==source for e in uses) for source in SOURCE_KINDS},
        }

    def update_prices(self):
        result = super().update_prices()
        for name,c in self.cs.items():
            production = [e for e in self.production_trace if e['country']==name and e['round']==self.r]
            previous = next((row for row in reversed(self.raw_round_ledger) if row['country']==name), None)
            flows = {g:{'imports':0, 'exports':0, 'purchases':0, 'sales':0} for g in RAW_GOODS}
            for tx in self.transactions:
                if tx['round'] != self.r:
                    continue
                for leg in tx['legs']:
                    good = self.units[leg['ids'][0]].good
                    if good not in RAW_GOODS:
                        continue
                    if leg['buyer']==name:flows[good]['imports'] += len(leg['ids'])
                    if leg['seller']==name:flows[good]['exports'] += len(leg['ids'])
                if tx['cash']:
                    payer,payee,amount = tx['cash']
                    good = self.units[tx['legs'][0]['ids'][0]].good
                    if good in RAW_GOODS:
                        if payer==name:flows[good]['purchases'] += amount
                        if payee==name:flows[good]['sales'] += amount
            self.raw_round_ledger.append({
                'round':self.r, 'country':name, 'cash':c.cash, 'happy':c.happy,
                'food_met':self.r in c.satisfied_rounds,
                'production_failures':sum(not e['funded'] for e in production),
                'machine_generation':c.machine_tech, 'electronics_generation':c.elec_tech,
                'goods':{g:{**self._raw_counts(name,g,self.r), **flows[g],
                            'opening_stock':previous['goods'][g]['stock'] if previous else self.starter_allocation[name][g],
                            'produced':sum(u.origin==name and u.good==g and u.born==self.r for u in self.units.values()),
                            'stock':self.count(c,g,False),
                            'machine_credits_by_grade':{str(grade):self.material_credit[(name,g,grade)] for grade in (1,2,3)},
                            'unmet_production':sum(max(0,e['required'].get(g,0)-e['available_before'][g]) for e in production)}
                         for g in RAW_GOODS},
            })
        return result

    def verify(self):
        # Reuse all v1-v5 money/goods/escrow/need checks. v6's sole fixed-size
        # credit checker is reproduced below with the instance parameter.
        # v7 introduces no verify override. No invariant is silently disabled.
        result = PhysicalChecks.verify(self)
        size = self.raw_policy.machine_credits
        assert all(type(v) is int and 0 <= v < size for v in self.material_credit.values())
        assert all(type(v) is int and 0 <= v < UPKEEP_USES for v in self.upkeep_wear.values())
        for e in self.material_events:
            assert e['credits_per_raw'] == size
            assert e['credits_after'] == e['credits_before']+size*e['raw_spent']-e['credits_spent']
        assert all(e['produced']==0 and not e['raw_used'] for e in self.machine_output_log if e['status']=='paused')
        assert all(e['generation']==1 and e['produced']==1 for e in self.machine_output_log if e['status']=='fallback')
        assert all(e['produced']<=e['capacity'] for e in self.machine_output_log)
        assert len({e['uid'] for e in self.raw_use_log}) == len(self.raw_use_log)
        for e in self.raw_use_log:
            u = self.units[e['uid']]
            assert u.good==e['good'] and u.owner is None and u.used
            assert (u.use_round,u.use_country,u.use_purpose)==(e['round'],e['country'],e['purpose'])
        return result

    def summary(self):
        result = super().summary()
        for name,c in self.cs.items():
            x = result['countries'][name]
            rows = [r for r in self.raw_round_ledger if r['country']==name]
            x['starter_raw'] = dict(self.starter_allocation[name])
            x['raw_use'] = {g:self._raw_counts(name,g) for g in RAW_GOODS}
            x['raw_import_rounds'] = {g:sum(r['goods'][g]['imports']>0 for r in rows) for g in RAW_GOODS}
            x['first_raw_import_round'] = {g:min((r['round'] for r in rows if r['goods'][g]['imports']),default=10) for g in RAW_GOODS}
            x['raw_importing'] = {g:int(any(r['goods'][g]['imports'] for r in rows)) for g in RAW_GOODS}
            x['initial_raw_left'] = {g:sum(self.units[i].good==g and self.units[i].born==0 for i in c.stock) for g in RAW_GOODS}
            x['raw_unmet_production'] = {g:sum(r['goods'][g]['unmet_production'] for r in rows) for g in RAW_GOODS}
            x['first_two_happy'] = statistics.mean(r['happy'] for r in rows if r['round']<=2)
            x['first_two_food_short'] = sum(not r['food_met'] for r in rows if r['round']<=2)
            x['first_two_production_failures'] = sum(r['production_failures'] for r in rows if r['round']<=2)
            x['first_round_happy'] = rows[0]['happy']
            x['first_round_production_failures'] = rows[0]['production_failures']
            x['start_asset_value'] = self.initial_assets[name]
            x['end_asset_value'] = c.cash+self.stock_value(c)+.45*c.investment
            x['cash_plus_stock_value'] = c.cash+self.stock_value(c)
            x['machine_free_basic'] = sum(e['country']==name and e['generation']==1 and e['produced']==1 and not e['raw_used'] and e['status']=='regular' for e in self.machine_output_log)
            for good in ('machine','electronics'):
                tech = self.tech_for(c,good)
                for grade in (2,3):
                    x[f'{good}_g{grade}'] = int(good in c.levels and tech>=grade)
            for g in RAW_GOODS:
                assert x['raw_use'][g]['production']==x['production_raw'][g]
                assert x['raw_use'][g]['research']==x['research_raw'][g]
                assert sum(r['goods'][g]['imports'] for r in rows)==x['import_goods'].get(g,0)
        w = result['world']
        for key in ('starter_raw','initial_raw_left','raw_importing','raw_import_rounds','raw_unmet_production'):
            w[key] = {g:sum(c[key][g] for c in result['countries'].values()) for g in RAW_GOODS}
        w['raw_use'] = {g:{key:sum(c['raw_use'][g][key] for c in result['countries'].values())
                            for key in self._raw_counts(next(iter(self.cs)),g)} for g in RAW_GOODS}
        for key in ('first_two_food_short','first_two_production_failures','first_round_production_failures',
                    'machine_free_basic','machine_g2','machine_g3','electronics_g2','electronics_g3'):
            w[key] = sum(c[key] for c in result['countries'].values())
        for key in ('first_two_happy','first_round_happy'):
            w[key] = statistics.mean(c[key] for c in result['countries'].values())
        w['initial_asset_value'] = sum(c['start_asset_value'] for c in result['countries'].values())
        w['end_asset_value'] = sum(c['end_asset_value'] for c in result['countries'].values())
        w['raw_policy'] = asdict(self.raw_policy)
        w['v7_note'] = 'v7 price advice inherited; v8 explicitly varies starter resources and machine-only material efficiency.'
        w['v8_note'] = 'Raw bundle prices, electronics/research recipes and all score formulas unchanged. No-starter profiles are boundary diagnostics.'
        return result

    def trace(self):
        result = super().trace()
        result.update(raw_use=self.raw_use_log, raw_ledger=self.raw_round_ledger,
                      starter_allocation=self.starter_allocation,
                      raw_policy=asdict(self.raw_policy))
        return result

files.trade_v17/source_v13/growth_scoring.py:
"""v12: frozen-economy, country-target and scoring-ceiling experiments.

The v11 economy and its official scores are inherited without edits.  This
module exposes two already-existing AI styles and provides pure, post-game
score views.  New target values are fitted only to a separate calibration set.
"""
from __future__ import annotations

from copy import deepcopy
import math

from evaluation_engine import Game as V11Game, BEHAVIORS as V11_BEHAVIORS
from reference_engine import NAMES, ECON_GOAL, GROWTH_GOAL, DURABLES

VIEWS = ('legacy', 'targets', 'headroom', 'targets_headroom')
CALIBRATION_STYLES = ('normal', 'invest', 'trade')
BEHAVIORS = V11_BEHAVIORS + ('invest', 'trade')
GOAL_METHOD = {
    'quantile': .75, 'economic_floor': 50, 'economic_step': 5,
    'industrial_floor': .10, 'industrial_step': .05,
    'policies': list(CALIBRATION_STYLES), 'equal_policy_weight': True,
    'original_countries_only': True,
    'exclude_peer_policy_observations': True,
}
HEADROOM = {'base_target_fraction': .8, 'challenge_target_multiple': 2.0}


class Game(V11Game):
    """Expose the inherited investment/trade policies; no economic rule change."""
    def __init__(self, seed=0, focal=None, style='normal', trade_enabled=True,
                 behaviors=None):
        if style not in BEHAVIORS:
            raise ValueError('unknown growth-validation behavior')
        if style in ('invest', 'trade'):
            if focal is None:
                raise ValueError('investment/trade behavior requires a focal country')
            other = dict(behaviors or {})
            if focal in other and other[focal] != style:
                raise ValueError('conflicting focal behavior')
            other.pop(focal, None)
            super().__init__(seed, focal=focal, style='normal',
                             trade_enabled=trade_enabled, behaviors=other)
            self.cs[focal].style = style
            self.behaviors[focal] = style
        else:
            super().__init__(seed, focal=focal, style=style,
                             trade_enabled=trade_enabled, behaviors=behaviors)


def finite(value, label):
    if type(value) not in (int, float) or not math.isfinite(value):
        raise ValueError(f'{label} must be a finite number')
    return value


def clip01(value):
    return min(1., max(0., value))


def curve(ratio, headroom=False):
    """Reach 80% at the base goal and 100% at twice that goal, if enabled."""
    finite(ratio, 'growth ratio')
    if not headroom:
        return clip01(ratio)
    return .8 * clip01(ratio) + .2 * clip01(ratio - 1.)


def percentile(values, quantile=.75):
    values = sorted(finite(v, 'calibration value') for v in values)
    if not values or not 0 <= quantile <= 1:
        raise ValueError('nonempty calibration values and a valid quantile required')
    position = (len(values)-1) * quantile
    index = int(position)
    fraction = position-index
    return values[index]*(1-fraction) + values[min(index+1, len(values)-1)]*fraction


def rounded_goal(value, floor, step):
    """Round up to a readable step; tolerate only binary representation noise."""
    value = max(floor, finite(value, 'goal quantile'))
    return round(math.ceil(value/step - 1e-12)*step, 10)


def extract_metrics(game, result):
    """Read final-state evidence, without choosing plans or issuing actions."""
    if game.r != 9 or len(game.round_history) != 9:
        raise ValueError('growth metrics require a completed nine-round game')
    out = {}
    for name, country in game.cs.items():
        x = result['countries'][name]
        owned = [game.units[i] for i in country.stock]
        unused_value = sum(game.unit_ref(u)*.15 for u in owned if not u.used)
        used_value = sum(game.unit_ref(u)*(.5 if u.good in DURABLES else .15)
                         for u in owned if u.used)
        initial_capacity = game.initial_capacity[name]
        final_capacity = game.capacity(country)
        reserve = game.reserve(country)
        produced = sum(x['produced'].values())
        used = x['all_goods_unique_used']
        if reserve <= 0 or initial_capacity <= 0 or not 0 <= used <= produced:
            raise AssertionError((name, 'invalid evidence for growth score'))
        stock_value = game.stock_value(country)
        assert math.isclose(unused_value+used_value, stock_value, abs_tol=1e-8)
        assert math.isclose(x['end_asset_value'],
                            country.cash+stock_value+.45*country.investment,
                            abs_tol=1e-8)
        growth = (final_capacity-initial_capacity)/initial_capacity
        assert math.isclose(growth, x['capacity_growth'], abs_tol=1e-12)
        out[name] = {
            'start_asset_value': x['start_asset_value'],
            'end_asset_value': x['end_asset_value'],
            'asset_gain': x['end_asset_value']-x['start_asset_value'],
            'cash': country.cash, 'tax': country.tax,
            'investment': country.investment,
            'unused_stock_value': unused_value,
            'used_stock_value': used_value,
            'stock_value': stock_value,
            'initial_capacity': initial_capacity,
            'final_capacity': final_capacity,
            'capacity_growth': growth,
            'reserve_target': reserve,
            'reserve_score': 5*clip01(country.cash/reserve),
            'produced_units': produced, 'used_units': used,
            'utilization': used/max(1, produced),
            'utilization_score': 10*used/max(1, produced),
            'wellbeing_score': x['happy']/4,
            'trade_score': x['trade'],
        }
    return out


def make_goals(records):
    """Fit each nation to its own normal/invest/trade results with equal weights.

    A control game is shared across nations, not counted as six independent
    economies. Outcomes of peers whose policy was not manipulated are excluded.
    """
    by_key = {}
    for row in records:
        if row.get('phase') != 'calibration':
            raise ValueError('only calibration records may define targets')
        key = (row['scenario'], row['seed'])
        if key in by_key:
            raise ValueError('duplicate calibration trajectory')
        by_key[key] = row
    normal_seeds = {seed for (sid, seed) in by_key if sid == 'None:normal'}
    if len(normal_seeds) < 2:
        raise ValueError('at least two paired calibration seeds required')
    expected_cases = {'None:normal'} | {f'{n}:{s}' for n in NAMES for s in ('invest','trade')}
    if set(by_key) != {(case, seed) for case in expected_cases for seed in normal_seeds}:
        raise ValueError('calibration must contain precisely the declared paired policies')
    economic = {}; industrial = {}; raw_economic = {}; raw_industrial = {}
    for name in NAMES:
        sample = []
        for style in CALIBRATION_STYLES:
            sid = 'None:normal' if style == 'normal' else f'{name}:{style}'
            for seed in sorted(normal_seeds):
                row = by_key[sid, seed]
                expected_focal = None if style == 'normal' else name
                if row['focal'] != expected_focal or row['style'] != style:
                    raise ValueError('calibration policy identity mismatch')
                sample.append(row['countries'][name]['growth_metrics'])
        raw_economic[name] = percentile([m['asset_gain'] for m in sample])
        raw_industrial[name] = percentile([m['capacity_growth'] for m in sample])
        economic[name] = rounded_goal(raw_economic[name], 50, 5)
        industrial[name] = rounded_goal(raw_industrial[name], .10, .05)
    return {
        'schema': 'v12-growth-targets-1', 'source': 'calibration_only',
        'method': deepcopy(GOAL_METHOD),
        'calibration': {
            'seeds': sorted(normal_seeds), 'n_per_policy': len(normal_seeds),
            'samples_per_country': 3*len(normal_seeds),
            'unique_economic_games': len(by_key),
        },
        'economic': economic, 'industrial': industrial,
        'raw_quantiles': {'economic': raw_economic, 'industrial': raw_industrial},
    }


def validate_goals(goals):
    if goals.get('schema') != 'v12-growth-targets-1' or goals.get('source') != 'calibration_only':
        raise ValueError('unexpected target file schema/source')
    if goals.get('method') != GOAL_METHOD:
        raise ValueError('target-setting method differs from the frozen protocol')
    for category in ('economic', 'industrial'):
        if set(goals[category]) != set(NAMES):
            raise ValueError('targets are required for precisely the original six nations')
        if any(finite(v, 'target') <= 0 for v in goals[category].values()):
            raise ValueError('targets must be positive')


def score_metrics(metrics, economic_target, industrial_target, headroom=False):
    for key, value in metrics.items():
        finite(value, key)
    if finite(economic_target, 'economic target') <= 0 or finite(industrial_target, 'industrial target') <= 0:
        raise ValueError('targets must be positive')
    m = metrics
    er = m['asset_gain']/economic_target
    ir = m['capacity_growth']/industrial_target
    econ_growth = 20*curve(er, headroom)
    capacity = 15*curve(ir, headroom)
    reserve = m['reserve_score']
    use = m['utilization_score']
    economic = econ_growth+reserve
    industry = capacity+use
    return {
        'economic_target': economic_target, 'industrial_target': industrial_target,
        'economic_ratio': er, 'industrial_ratio': ir,
        'economic_growth': econ_growth, 'reserve': reserve,
        'economic': economic, 'capacity': capacity,
        'utilization': use, 'industry': industry,
        'wellbeing': m['wellbeing_score'], 'trade': m['trade_score'],
        'score': economic+industry+m['wellbeing_score']+m['trade_score'],
        'economic_growth_at_cap': int(econ_growth >= 20-1e-9),
        'capacity_at_cap': int(capacity >= 15-1e-9),
        'economic_growth_near_cap': int(econ_growth >= 19-1e-9),
        'capacity_near_cap': int(capacity >= 14.25-1e-9),
        'economic_at_cap': int(economic >= 25-1e-9),
        'economic_5pct_sensitivity': 20*(curve(max(0, er)*1.05, headroom)-curve(er, headroom)),
        'capacity_5pct_sensitivity': 15*(curve(max(0, ir)*1.05, headroom)-curve(ir, headroom)),
    }


def score_record(record, goals):
    """Return a new record; official fields and economic trajectories stay intact."""
    validate_goals(goals)
    output = deepcopy(record)
    for name, country in output['countries'].items():
        if name not in NAMES:
            country['growth_evaluation'] = {view: None for view in VIEWS}
            continue
        metrics = country['growth_metrics']
        views = {}
        for view in VIEWS:
            fitted = view in ('targets','targets_headroom')
            et = goals['economic'][name] if fitted else ECON_GOAL[name]
            it = goals['industrial'][name] if fitted else GROWTH_GOAL[name]
            views[view] = score_metrics(metrics, et, it, 'headroom' in view)
        for key in ('economic', 'industry', 'score'):
            assert math.isclose(views['legacy'][key], country[key], abs_tol=1e-9), (name,key)
            views['legacy'][key] = country[key]
        assert math.isclose(views['legacy']['capacity'], country['industry_capacity_score'], abs_tol=1e-9)
        assert math.isclose(views['legacy']['utilization'], country['industry_use_score'], abs_tol=1e-9)
        country['growth_evaluation'] = views
    output['world']['growth_evaluation_config'] = {
        'views': list(VIEWS), 'headroom': deepcopy(HEADROOM),
        'economic_rules_unchanged': True, 'official_scores_unchanged': True,
        'score_feedback_to_actions': False, 'ranked_countries': list(NAMES),
        'v11_trade_view': 'legacy', 'asset_definition_unchanged': True,
        'utilization_definition_unchanged': True,
    }
    return output
